#include <windows.h>
#include <stdio.h>

static HHOOK g_hook = nullptr;

static LRESULT CALLBACK OnCallWnd(int code, WPARAM wparam, LPARAM lparam) {
    return CallNextHookEx(g_hook, code, wparam, lparam);
}

int main() {
    g_hook = SetWindowsHookExA(WH_CALLWNDPROC, OnCallWnd, nullptr,
        GetCurrentThreadId());
    if (g_hook == nullptr) {
        return 1;
    }

    // The hook is limited to the current thread and removed immediately.
    UnhookWindowsHookEx(g_hook);
    return 0;
}

